using System;using System.IO;using System.Linq;using System.Collections;using UnityEngine;using UnityEngine.UI;
public static class NWScythe {
 static NewWeaponCombat n;static CombatEnemy enemy;static int contacts,releases,pulls,blocked,immune;static string root;static void Trace(NewWeaponCombat.Trace t){if(t.stage=="contact"&&t.after<t.before)contacts++;if(t.stage=="release")releases++;if(t.stage=="pull-start")pulls++;if(t.stage=="pull-obstructed"||t.stage=="obstructed")blocked++;if(t.stage=="control-immune")immune++;File.AppendAllText(root+"/scythe-trace.jsonl",JsonUtility.ToJson(new Entry{stage=t.stage,a=t.a,b=t.b,before=t.before,after=t.after,radius=t.radius,time=t.time})+"\n");}[Serializable]class Entry{public string stage;public Vector3 a,b;public float before,after,radius,time;}
 static void Move(CombatEnemy e,Vector3 pos){var cc=e.GetComponent<CharacterController>();cc.enabled=false;e.transform.position=pos;cc.enabled=true;}
 static IEnumerator Restart(NWProbe p){var h=CP05Training.Instance.Hero;CP05Training.Instance.RequestRestart();yield return p.Wait(()=>CP05Training.Instance.Hero!=h&&!CP05Training.Instance.Restarting,6);yield return null;yield return null;}
 static IEnumerator Setup(NWProbe p){yield return p.Wait(()=>UnityEngine.Object.FindObjectsByType<Button>().Any(b=>b.name=="训练装备架"),5);var h=CP05Training.Instance.Hero;UnityEngine.Object.FindObjectsByType<Button>().Single(b=>b.name=="训练装备架").onClick.Invoke();yield return null;yield return null;var loot=UnityEngine.Object.FindObjectsByType<LootPickup>().Single(x=>x.Gear?.type==GearType.Scythe);p.Check("scythe-pickup",loot.PickUp(h.Inventory));var c=h.GetComponent<AdventureCombat>();p.Check("scythe-equip",c.Gear.SelectMain(loot.Gear));yield return new WaitForSeconds(.3f);n=c.NewWeapons;p.Check("scythe-model",n.Visual.Ready&&n.Visual.Left==null&&n.Visual.Right.parent.name=="handslot.r");enemy=CP05Training.Instance.Enemies[0];enemy.enabled=false;CP05Training.Instance.Enemies[1].gameObject.SetActive(false);Move(enemy,h.transform.position+Vector3.forward*2.5f);h.transform.rotation=Quaternion.identity;h.cameraTransform.GetComponent<OrbitCamera>().enabled=false;h.cameraTransform.position=h.transform.position+new Vector3(0,3,-5);h.cameraTransform.LookAt(enemy.transform.position+Vector3.up);contacts=releases=pulls=blocked=immune=0;n.Observed+=Trace;PlayerInput.Focus(true);yield return null;yield return null;}
 public static IEnumerator Run(NWProbe p){root=p.Root;yield return p.Wait(()=>CP05Training.Instance?.Hero!=null,15);yield return Setup(p);var h=n.Hero;var c=n.Combat;enemy.gameObject.AddComponent<BoxCollider>().center=Vector3.up;float before=enemy.Health.Current;p.Check("scythe-basic",c.Strike());yield return new WaitForSeconds(.7f);p.Check("scythe-basic-unique",contacts==1&&enemy.Health.Current<before);yield return Shot(p,"scythe-basic.png");
 yield return Restart(p);yield return Setup(p);h=n.Hero;c=n.Combat;var other=CP05Training.Instance.Enemies[1];other.gameObject.SetActive(true);other.enabled=false;Move(other,h.transform.position+new Vector3(-1,0,2));Move(enemy,h.transform.position+new Vector3(1,0,2));enemy.gameObject.AddComponent<BoxCollider>().center=Vector3.up;p.Check("scythe-reap",c.UseSkill());yield return new WaitForSeconds(1.3f);p.Check("scythe-three-phases-two-targets",releases==3&&contacts==6&&enemy.Health.Current<60&&other.Health.Current<60,"per phase per target once, not per Collider");yield return Shot(p,"scythe-reap.png");
 yield return Restart(p);yield return Setup(p);h=n.Hero;c=n.Combat;Move(enemy,h.transform.position+Vector3.forward*3.5f);before=Vector3.Distance(enemy.transform.position,h.transform.position);n.Select(1);yield return null;yield return null;p.Check("pull-request",c.UseSkill());p.Check("pull-cooldown",!c.UseSkill());yield return new WaitForSeconds(.5f);float first=Vector3.Distance(enemy.transform.position,h.transform.position);p.Check("pull-bounded-not-teleport",pulls==1&&first<before&&first>before-.6f,"real CharacterController.Move at existing speed/mass proxy");h.Inventory.SetOpen(true);Vector3 position=enemy.transform.position;yield return p.Wait(()=>false,.4f);p.Check("pull-pause",Vector3.Distance(position,enemy.transform.position)<.001f);h.Inventory.SetOpen(false);yield return new WaitForSeconds(1);p.Check("pull-resume-and-expire",enemy.GetComponent<EnemyWeaponControl>().PullRemaining==0&&Vector3.Distance(enemy.transform.position,h.transform.position)<first);yield return Shot(p,"scythe-pull.png");
 yield return Restart(p);yield return Setup(p);h=n.Hero;c=n.Combat;before=enemy.Health.Current;var wall=GameObject.CreatePrimitive(PrimitiveType.Cube);wall.transform.position=h.transform.position+new Vector3(0,1,1.1f);wall.transform.localScale=new Vector3(4,3,.2f);position=enemy.transform.position;n.Select(1);yield return null;yield return null;p.Check("pull-wall-request",c.UseSkill());yield return new WaitForSeconds(1.4f);p.Check("pull-wall-no-motion",pulls==0&&blocked>0&&Vector3.Distance(position,enemy.transform.position)<.02f&&enemy.Health.Current==before);
 yield return Restart(p);yield return Setup(p);h=n.Hero;c=n.Combat;enemy.archetype=EnemyArchetype.Boss;position=enemy.transform.position;n.Select(1);yield return null;yield return null;p.Check("pull-boss-request",c.UseSkill());yield return new WaitForSeconds(1.1f);p.Check("pull-boss-immune",immune==1&&pulls==0&&enemy.transform.position==position,"synthetic Boss archetype uses same explicit production immunity");
 yield return Restart(p);yield return Setup(p);h=n.Hero;c=n.Combat;Move(enemy,h.transform.position-Vector3.forward*2);before=enemy.Health.Current;p.Check("scythe-back-request",c.Strike());yield return new WaitForSeconds(.8f);p.Check("scythe-back-not-hit",contacts==0&&enemy.Health.Current==before);
 }
 static IEnumerator Shot(NWProbe p,string name){yield return new WaitForEndOfFrame();var t=ScreenCapture.CaptureScreenshotAsTexture();File.WriteAllBytes(p.Root+"/"+name,t.EncodeToPNG());UnityEngine.Object.Destroy(t);}
}
